    "glossary": [
      {
        "term": "Market definition",
        "def": "The boundary drawn around the set of products and buyers treated as one market. Determines share, rivals, growth rate and visible threats."
      },
      {
        "term": "Product form competition",
        "def": "Rivals offering the same product in the same configuration. The narrowest level, and what share reports usually measure."
      },
      {
        "term": "Generic competition",
        "def": "Anything meeting the same underlying customer need by different means. Where substitutes live."
      },
      {
        "term": "Budget competition",
        "def": "Everything competing for the same money at the same moment, across categories."
      },
      {
        "term": "Hypothetical monopolist test (SSNIP)",
        "def": "Ask whether a single owner of everything inside a candidate boundary could impose a small but significant non-transitory price rise, typically 5–10%. If not, the boundary is too narrow."
      },
      {
        "term": "TAM",
        "def": "Total addressable market — everyone who could conceivably buy the category. An upper bound, not a forecast."
      },
      {
        "term": "SAM",
        "def": "Served available market — the part your model can actually reach, given geography, channel, segment and price."
      },
      {
        "term": "SOM",
        "def": "Serviceable obtainable market — what you could realistically win in a period, against competitors who already hold it."
      },
      {
        "term": "Volume share",
        "def": "Share measured in units sold. Flatters low-priced brands."
      },
      {
        "term": "Value share",
        "def": "Share measured in revenue. Flatters premium brands."
      }
    ],
