    "glossary": [
      {
        "term": "Competitive set",
        "def": "The list of alternatives a customer would genuinely consider for the same job. Built from the customer's side, not from the industry classification."
      },
      {
        "term": "Four corners",
        "def": "Porter's model of a rival: current strategy, objectives, capabilities, and assumptions. The last predicts behaviour and is the least collected."
      },
      {
        "term": "Assumptions",
        "def": "What a rival believes about the market without checking. Found in what it refuses to do, not in what it says."
      },
      {
        "term": "Reaction profile",
        "def": "How a rival typically responds to attack: laid-back, selective, tiger, or unpredictable."
      },
      {
        "term": "Selective competitor",
        "def": "A rival that defends some moves fiercely and ignores others. The most common profile and the most learnable."
      },
      {
        "term": "Competitive intelligence",
        "def": "Systematic collection and analysis of public information about rivals. Legitimate when it relies on observation; illegitimate when it relies on deception."
      },
      {
        "term": "Blind spot",
        "def": "The area a firm cannot see because of how it has defined its industry — typically the level-three and level-four rivals."
      },
      {
        "term": "Ecosystem",
        "def": "A product plus the complements built around it. Nokia's model treated software as a feature; its rivals treated it as the product."
      }
    ],
