    "glossary": [
      {
        "term": "SWOT",
        "def": "Strengths, weaknesses, opportunities, threats. Internal and external factors, helpful and harmful, on one page."
      },
      {
        "term": "Internal factor",
        "def": "Something the firm owns or controls. If the statement would still be true after the firm disappeared, it is not internal."
      },
      {
        "term": "Parity",
        "def": "A capability all serious rivals also have. Necessary to compete, insufficient to win, and wrongly filed as a strength."
      },
      {
        "term": "Table stakes",
        "def": "The minimum required to be considered at all. Another name for parity."
      },
      {
        "term": "TOWS",
        "def": "The conversion step: pairing internal with external factors to produce four strategies — SO, ST, WO, WT."
      },
      {
        "term": "SO strategy",
        "def": "Use a strength to take an opportunity. The attacking quadrant."
      },
      {
        "term": "ST strategy",
        "def": "Use a strength to blunt a threat. The defensive quadrant."
      },
      {
        "term": "WO strategy",
        "def": "An opportunity blocked by a weakness: fix it, partner, buy the capability, or let it go deliberately."
      },
      {
        "term": "WT strategy",
        "def": "Exposed to a threat with no capability to answer it. Produces exits and insurance, and is the cell firms skip."
      },
      {
        "term": "Cannibalisation",
        "def": "Taking sales from your own product with a new one. Frequently the price of acting on a correct analysis."
      }
    ],
